import React, { useState, useRef, useEffect } from 'react';
import Tips from '../Tips/Tips';
import Employees from '../Employees/Employees';
import Summary from '../Summary/Summary';
import { GrAdd, GrUserManager, GrDocumentText } from 'react-icons/gr';
import './Tabs.css';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
// import { faKeyboard, faHashtag, faBars, faCodepen, faDribbble, faTwitter } from '@fortawesome/free-solid-svg-icons';

const tabs = [
  { title: 'Add Tips', icon: <GrAdd />, component: Tips },
  { title: 'Manage Employees', icon: <GrUserManager />, component: Employees },
  { title: 'View Summary', icon: <GrDocumentText />, component: Summary },
  {},
  {},
  {}
];

const Tabs = () => {
  const [activeSlide, setActiveSlide] = useState('Slide1');

  const slides = [
    {
      id: 'Slide1',
      title: 'Home',
      content: (
        <>
          <h1><strong>Pure CSS</strong> one page vertical navigation</h1>
          <div className="icon">
            <span>Use keyboard</span>
          </div>
        </>
      )
    },
    {
      id: 'Slide2',
      title: 'Features',
      content: (
        <>
          <h1>Features</h1>
          <div className="block">
            <span><strong>No JS</strong><br/>CSS Rules!</span>
            <span><strong>Pure CSS keyboard navigation</strong><br/>Yep, no kidding</span>
            <span><strong>Lateral menu</strong></span>
            <span><strong>Autogenerate pages</strong><br/>Using Jade & SASS</span>
          </div>
        </>
      )
    },
    {
      id: 'Slide3',
      title: 'Adding pages to this template',
      content: (
        <>
          <h1>Adding pages to this template</h1>
          <div className="block">
            <ol>
              <li>Add the pages title in the pageTitle array in the HTML editor to generate pages</li>
              <li>Add the number of pages in the $npages variable in the CSS editor</li>
            </ol>
          </div>
        </>
      )
    },
    {
      id: 'Slide4',
      title: '+More',
      content: (
        <>
          <h1>+More</h1>
          <div className="block">
            <span><a href="https://codepen.io/hrtzt/pen/NPZKRN" target="_blank" rel="noopener noreferrer">One Page Navigation CSS Menu</a></span>
            <span><a href="https://codepen.io/hrtzt/pen/YPoeWd" target="_blank" rel="noopener noreferrer">The simplest CSS switch</a></span>
            <span><a href="https://codepen.io/hrtzt/pen/JdYaEZ" target="_blank" rel="noopener noreferrer">Animated cube slider CSS only</a></span>
            <span><a href="https://codepen.io/hrtzt/pen/vGqEJO" target="_blank" rel="noopener noreferrer">Google photos album view with only CSS</a></span>
          </div>
        </>
      )
    },
    {
      id: 'Slide5',
      title: 'About',
      content: (
        <>
          <h1>About</h1>
          <div className="block">
            <span><a href="https://dribbble.com/hrtzt" target="_blank" rel="noopener noreferrer"> Dribbble me</a></span>
            <span><a href="https://twitter.com/hrtzt" target="_blank" rel="noopener noreferrer"><FontAwesomeIcon icon={faTwitter} /> Tweet me</a></span>
          </div>
        </>
      )
    },
    {
      id: 'Slide6',
      title: 'Dummy page',
      content: (
        <>
          <h1>Dummy page</h1>
          <div className="block">Lorem ipsum dolor sit amet, consectetur adipisicing elit. Architecto numquam, totam iusto officia earum perferendis</div>
        </>
      )
    },
    {
      id: 'Slide7',
      title: 'Dummy page',
      content: (
        <>
          <h1>Dummy page</h1>
          <div className="block">Lorem ipsum dolor sit amet, consectetur adipisicing elit. Architecto numquam, totam iusto officia earum perferendis</div>
        </>
      )
    }
  ];

  return (
    <div className="contenedor">
      <div className="labels">
        {slides.map((slide) => (
          <label
            key={slide.id}
            className={`Slide ${activeSlide === slide.id ? 'active' : ''}`}
            htmlFor={slide.id}
            id={slide.id}
            onClick={() => setActiveSlide(slide.id)}
          >
            <div className="content">
              {slide.content}
            </div>
          </label>
        ))}
      </div>
    </div>
  );
};

export default Tabs;
